	"crypto/rsa"
	"crypto/x509"
	"encoding/pem"
)

// Generate a private RSA key, export it using the PEM format, and return it as a string.
func CreatePrivateKey() string {
	// Generate a new RSA private key with 2048 bits.
	// 2048 bits is a commonly accepted secure key size for RSA, offering a good balance
	// between security and performance for current cryptographic standards.
	privateKey, err := rsa.GenerateKey(rand.Reader, 2048)
	if err != nil {
		// Panicking is used here because the function signature does not allow returning an error.
		// In a production environment, a function returning (string, error) would be preferred
		// to allow callers to handle key generation failures gracefully.
		panic("Failed to generate RSA private key: " + err.Error())
	}

	// Marshal the private key to PKCS#8 DER format.
	// PKCS#8 is a modern, secure, and recommended format for private keys,
	// supporting various algorithms and providing better extensibility than PKCS#1.
	privateKeyDER, err := x509.MarshalPKCS8PrivateKey(privateKey)
	if err != nil {
		panic("Failed to marshal private key to PKCS#8: " + err.Error())
	}

	// Create a PEM block for the private key.
	// The type "PRIVATE KEY" is the standard label for PKCS#8 encoded private keys
	// when represented in PEM format.
	privateKeyPEM := &pem.Block{
		Type:  "PRIVATE KEY",
		Bytes: privateKeyDER,
	}

	// Encode the PEM block to a bytes buffer.
	// This converts the structured PEM block into its base64-encoded string representation,
	// delimited by PEM headers and footers.
	var pemBuffer bytes.Buffer
	if err := pem.Encode(&pemBuffer, privateKeyPEM); err != nil {
		panic("Failed to encode PEM block: " + err.Error())
	}

	// Return the PEM encoded private key as a string.
	return pemBuffer.String()
}
